INSERT INTO destinations (id, destination_name, state_id, city_id, district, region, latitude, longitude, altitude_m, popularity_score, accessibility, nearest_airport, nearest_railway, nearest_major_city, nearest_major_city_distance_km, road_connectivity, trip_types, primary_attractions, activities_available, unique_experiences, hidden_gems, best_seasons, avoid_seasons, peak_season, off_season, average_temperature, rainfall_pattern, ideal_for, ideal_for_why, special_considerations, minimum_days, ideal_days, maximum_days, suggested_itinerary, accommodation_types, food_scene, safety_rating, safety_notes, internet_connectivity, mobile_network, atm_availability, language_spoken, permits_required, permits_details, local_culture, festivals_events, local_customs, shopping_highlights, local_cuisine_must_try, budget_range_json, mid_range_json, luxury_range_json, description, user_reviews_summary, recent_developments, sustainability_notes) VALUES ('dest-1', 'Goa', 'IN-GA', 'north-goa', 'North Goa, South Goa', 'West India', 15.3, 73.8, 50, 9.0, 'Easy', '{"name": "Dabolim Airport", "distance_km": 22}'::jsonb, '{"name": "Margao Railway Station", "distance_km": 35}'::jsonb, 'Bengaluru', 600.0, 'Excellent', '{"Beach","Cultural","Food","Nightlife","Wellness","Photography"}', '{"Baga Beach","Calangute Beach","Old Goa Churches","Fort Aguada","Dudhsagar Falls","Spice Plantations"}', '{"Beach hopping","Water sports","Temple and church visits","Ayurveda spas","Nightlife","River cruise"}', 'Indo-Portuguese heritage, vibrant nightlife, spice plantations, waterfall excursions', 'Palolem Beach | Agonda Beach | Arambol Beach | Morjim Beach | Netravali Lake | Tambdi Surla Temple', 'Winter | Post-Monsoon', 'Peak Monsoon', 'December-January', 'May-September', '{"winter": "20-32\u00b0C", "summer": "25-35\u00b0C", "monsoon": "22-30\u00b0C"}'::jsonb, 'Heavy monsoon June-September; coastal humidity high year-round', '{"Solo","Couple","Family_with_kids","Family_with_elderly","Friends"}', '{"Couple": "Romantic sunsets, beach stays, quiet South Goa beaches", "Friends": "Nightlife, water sports, party beaches", "Solo": "Safe, easy to navigate, lots of hostels and social activities", "Family_with_kids": "Gentle beaches, resorts with pools and activities", "Family_with_elderly": "Good medical facilities, easy transport, plenty of relaxed sightseeing"}'::jsonb, 'Very crowded and expensive in Christmas–New Year week; respect dress codes in churches and temples.', 2.0, 5.0, 10, 'Day 1: Panjim & Old Goa churches; Day 2: North Goa beaches (Baga, Calangute, Aguada); Day 3: South Goa (Colva, Palolem); Day 4: Dudhsagar Falls & spice plantation; Day 5: Leisure, river cruise, shopping.', 'Hotels | Resorts | Homestays | Beach shacks (seasonal) | Hostels', 'Excellent seafood, Goan cuisine, beach shacks, many vegetarian and international options.', 7.0, 'Generally safe; occasional petty theft near crowded beaches and nightlife areas.', 'Excellent in main beach belts and towns.', 'Jio | Airtel | Vi', 'Widely available in towns and main beaches.', 'Konkani | Marathi | Hindi | English', FALSE, 'Not required', 'Strong Catholic and Konkani traditions with visible Portuguese architectural influence.', 'Carnival (Feb-Mar), Shigmo, Christmas and New Year celebrations, Feast of St. Francis Xavier.', 'Remove footwear in temples; modest clothing in churches; avoid loud behaviour in residential areas at night.', 'Spices | cashews | feni | handicrafts | beachwear.', 'Goan fish curry rice | Prawn balchao | Pork vindaloo | Bebinca | Feni', '{"accommodation_range": [800, 1500], "food_range": [300, 600], "activities_range": [200, 500], "local_transport_range": [100, 200], "total_daily_range": [1400, 2800]}'::jsonb, '{"accommodation_range": [2000, 4000], "food_range": [600, 1200], "activities_range": [500, 1000], "local_transport_range": [200, 400], "total_daily_range": [3300, 6600]}'::jsonb, '{"accommodation_range": [8000, 20000], "food_range": [1500, 3000], "activities_range": [1000, 2500], "local_transport_range": [300, 600], "total_daily_range": [10800, 26100]}'::jsonb, 'Experience Goa in Goa.', 'Great mix of beaches, nightlife, and heritage; best in winter; monsoon is quiet but very wet.', 'Improved coastal safety measures and upgraded tourism facilities in 2024–2025.', 'Plastic restrictions on several beaches; support eco-certified operators where possible.') ON CONFLICT (id) DO NOTHING;
INSERT INTO destinations (id, destination_name, state_id, city_id, district, region, latitude, longitude, altitude_m, popularity_score, accessibility, nearest_airport, nearest_railway, nearest_major_city, nearest_major_city_distance_km, road_connectivity, trip_types, primary_attractions, activities_available, unique_experiences, hidden_gems, best_seasons, avoid_seasons, peak_season, off_season, average_temperature, rainfall_pattern, ideal_for, ideal_for_why, special_considerations, minimum_days, ideal_days, maximum_days, suggested_itinerary, accommodation_types, food_scene, safety_rating, safety_notes, internet_connectivity, mobile_network, atm_availability, language_spoken, permits_required, permits_details, local_culture, festivals_events, local_customs, shopping_highlights, local_cuisine_must_try, budget_range_json, mid_range_json, luxury_range_json, description, user_reviews_summary, recent_developments, sustainability_notes) VALUES ('dest-2', 'Ladakh (Leh)', 'IN-LA', 'leh', 'Leh, Kargil', 'North India', 34.16, 77.58, 3505, 9.0, 'Moderate', '{"name": "Kushok Bakula Rimpochee Airport (Leh)", "distance_km": 5}'::jsonb, '{"name": "Jammu Tawi", "distance_km": 420}'::jsonb, 'Srinagar', 420.0, 'Good but seasonal; highways via Manali and Srinagar close in peak winter.', '{"Adventure","Nature","Cultural","Religious","Photography","Trekking"}', '{"Leh Palace","Shanti Stupa","Pangong Tso","Nubra Valley","Khardung La","Tso Moriri","Hemis Monastery"}', '{"High-altitude trekking","Motorbike touring","River rafting (Zanskar)","Monastery visits","Camping","4x4 road trips"}', 'High-altitude desert landscapes, monasteries, starry night skies, challenging mountain passes.', 'Turtuk (in Nubra region) | Alchi Monastery | Hemis National Park | Remote villages like Hanle', 'Summer | Early Autumn', 'Deep Winter', 'June-August', 'November-March', '{"winter": "-15 to -5\u00b0C", "summer": "10-25\u00b0C (day), can go below 5\u00b0C at night", "monsoon": "data_not_available"}'::jsonb, 'Very low rainfall; cold desert climate with snow in winter.', '{"Adventure_seekers","Photographers","Trekking_enthusiasts","Couples","Friends"}', '{"Adventure_seekers": "High passes, remote valleys, rugged terrain.", "Photographers": "Dramatic mountains, lakes, night skies.", "Trekking_enthusiasts": "Multiple trekking routes and homestay trails."}'::jsonb, 'Risk of altitude sickness; acclimatise 24–48 hours in Leh; some border areas require permits.', 4.0, 7.0, 14, 'Day 1–2: Leh acclimatisation and local sights; Day 3–4: Nubra Valley; Day 5: Pangong day/overnight; Day 6: Monasteries; Day 7: Buffer/extra exploration.', 'Guesthouses | Hotels | Homestays | Luxury camps (seasonal)', 'Local Tibetan and Ladakhi dishes, basic North Indian, limited Western options.', 8.0, 'Low crime but high environmental risk (altitude, weather); keep permits handy in checkpost areas.', 'Improving in Leh town; patchy or absent in remote valleys.', 'Jio | Airtel | BSNL (spotty outside Leh)', 'Several ATMs in Leh; carry cash for remote areas.', 'Ladakhi | Hindi | English', TRUE, 'Inner Line Permits required for areas like Nubra, Pangong, Tso Moriri (check latest rules before travel).', 'Tibetan Buddhist cultural region with monasteries and traditional villages.', 'Hemis Festival, Losar (New Year), various monastery festivals.', 'Remove shoes in monasteries; ask before photographing locals or rituals; avoid loud behaviour.', 'Pashmina shawls | Handicrafts | Prayer flags | Thangka paintings', 'Momos | Thukpa | Butter tea | Skyu | Apricot products', '{"accommodation_range": [600, 1500], "food_range": [400, 800], "activities_range": [300, 700], "local_transport_range": [200, 400], "total_daily_range": [1500, 3400]}'::jsonb, '{"accommodation_range": [2000, 4000], "food_range": [800, 1500], "activities_range": [700, 1500], "local_transport_range": [400, 700], "total_daily_range": [3900, 7700]}'::jsonb, '{"accommodation_range": [7000, 15000], "food_range": [1500, 3000], "activities_range": [1500, 3000], "local_transport_range": [700, 1500], "total_daily_range": [10700, 22500]}'::jsonb, 'Experience Ladakh (Leh) in Ladakh.', 'Spectacular but demanding destination; preparation for altitude and weather is essential.', 'Road and airport upgrades and new homestays have expanded options for visitors.', 'Water is scarce; avoid plastic, use refillable bottles, and respect fragile high-altitude ecosystems.') ON CONFLICT (id) DO NOTHING;
