INSERT INTO destinations (id, destination_name, state_id, city_id, district, region, latitude, longitude, altitude_m, popularity_score, accessibility, nearest_airport, nearest_railway, nearest_major_city, nearest_major_city_distance_km, road_connectivity, trip_types, primary_attractions, activities_available, unique_experiences, hidden_gems, best_seasons, avoid_seasons, peak_season, off_season, average_temperature, rainfall_pattern, ideal_for, ideal_for_why, special_considerations, minimum_days, ideal_days, maximum_days, suggested_itinerary, accommodation_types, food_scene, safety_rating, safety_notes, internet_connectivity, mobile_network, atm_availability, language_spoken, permits_required, permits_details, local_culture, festivals_events, local_customs, shopping_highlights, local_cuisine_must_try, budget_range_json, mid_range_json, luxury_range_json, description, user_reviews_summary, recent_developments, sustainability_notes) VALUES ('dest-31', 'Havelock Island (Swaraj Dweep)', 'IN-AN', 'south-andaman', 'South Andaman', 'Island Territory', 11.968, 92.987, 0, 9.0, 'Moderate', '{"name": "Port Blair (Veer Savarkar International Airport)", "distance_km": 60}'::jsonb, '{"name": "None (island; access via ferry from Port Blair)", "distance_km": null}'::jsonb, 'Port Blair', 60.0, 'Internal island roads connect jetty, Radhanagar Beach and other points; main access is by ship/ferry from Port Blair.[web:216][web:217][web:222]', '{"Beach","Honeymoon","Diving","Family","Island"}', '{"Radhanagar Beach (Beach No. 7)","Elephant Beach (snorkelling/activities)","Kalapathar Beach","Neil’s Cove (near Radhanagar)"}', '{"Beach walks and sunset at Radhanagar","Snorkelling and scuba diving","Sea walking and other water sports (Elephant Beach)","Cycling or scooty rides"}', 'White-sand blue-water beaches including Radhanagar, often rated among Asia’s best beaches, with spectacular sunsets.[web:215][web:216][web:219][web:222]', 'Neil’s Cove lagoon at the far end of Radhanagar Beach.[web:216] | Quieter stretches of Kalapathar Beach during early mornings', 'Winter | Calm sea months from November to April', 'Peak monsoon and days of rough sea when ferries and water activities may be disrupted.[web:217][web:219]', 'December–March and holiday periods', 'Monsoon (June–September) and some shoulder weeks', '{"winter": "23-30\u00b0C", "summer": "26-33\u00b0C", "monsoon": "24-30\u00b0C"}'::jsonb, 'Tropical island with heavy monsoon showers; humidity high year-round.[web:217]', '{"Honeymooners","Families","Water_sports_lovers","Beach_relaxation_seekers"}', '{"Honeymooners": "Top-rated beaches, scenic sunsets and many resorts in quiet settings.[web:215][web:216]", "Water_sports_lovers": "Popular diving, snorkelling and sea-walk destination of Andamans.[web:217][web:218]"}'::jsonb, 'Ferry tickets between Port Blair and Havelock must be booked in advance in peak season; strict rules on plastic and beach cleanliness.', 2.0, 3.0, 5, 'Day 1: Arrival and Kalapathar or nearby beach; Day 2: Radhanagar Beach afternoon till sunset; Day 3: Water sports at Elephant Beach; extra days for diving or relaxing.[web:216][web:217][web:219][web:222]', 'Beach resorts (budget to luxury) | Island hotels | Eco-stays', 'Resort and beachside restaurants with Indian and international menus; fresh seafood popular.[web:217]', 9.0, 'Tourism infrastructure well-developed; follow lifeguard flags and dive operator safety briefings.', 'Improving 4G but still patchy; many resorts provide Wi‑Fi with varying speeds.[web:217]', 'BSNL | Jio and Airtel in some pockets', 'Very limited; advisable to carry cash from Port Blair.[web:217]', 'Hindi | Bengali | Tamil | English (tourism)', FALSE, 'Not required', 'Mixed settler communities with tourism-driven economy; strong focus on marine conservation.', 'Standard Indian festivals and occasional island-level tourism events.', 'Dress codes relaxed on beaches; avoid alcohol or littering on public beaches.', 'Small souvenir shops | Shell and handicraft items | Locally-themed T‑shirts', 'Fresh grilled seafood | Coconut-based curries | Island-style Indian and continental dishes', '{"accommodation_range": [1200, 2500], "food_range": [300, 700], "activities_range": [500, 1500], "local_transport_range": [300, 800], "total_daily_range": [2300, 5500]}'::jsonb, '{"accommodation_range": [2500, 6000], "food_range": [600, 1500], "activities_range": [800, 2000], "local_transport_range": [500, 1200], "total_daily_range": [4400, 10700]}'::jsonb, '{"accommodation_range": [6000, 20000], "food_range": [1000, 2500], "activities_range": [1500, 4000], "local_transport_range": [800, 1500], "total_daily_range": [9300, 28000]}'::jsonb, 'Experience Havelock Island (Swaraj Dweep) in Andaman and Nicobar Islands.', 'Frequently described as a highlight of Andaman trips thanks to Radhanagar’s beauty and good mix of relaxation and activities.', 'More mid-range and upscale resorts, better high-speed ferries and increased focus on sustainable tourism.', 'Coral and marine life sensitive to disturbance; choose certified dive operators and avoid touching corals or leaving waste.') ON CONFLICT (id) DO NOTHING;
INSERT INTO destinations (id, destination_name, state_id, city_id, district, region, latitude, longitude, altitude_m, popularity_score, accessibility, nearest_airport, nearest_railway, nearest_major_city, nearest_major_city_distance_km, road_connectivity, trip_types, primary_attractions, activities_available, unique_experiences, hidden_gems, best_seasons, avoid_seasons, peak_season, off_season, average_temperature, rainfall_pattern, ideal_for, ideal_for_why, special_considerations, minimum_days, ideal_days, maximum_days, suggested_itinerary, accommodation_types, food_scene, safety_rating, safety_notes, internet_connectivity, mobile_network, atm_availability, language_spoken, permits_required, permits_details, local_culture, festivals_events, local_customs, shopping_highlights, local_cuisine_must_try, budget_range_json, mid_range_json, luxury_range_json, description, user_reviews_summary, recent_developments, sustainability_notes) VALUES ('dest-32', 'Neil Island (Shaheed Dweep)', 'IN-AN', 'south-andaman', 'South Andaman', 'Island Territory', 11.83, 93.05, 0, 7.0, 'Moderate', '{"name": "Port Blair (via ferry)", "distance_km": 40}'::jsonb, '{"name": "None (island; ferry access only)", "distance_km": null}'::jsonb, 'Port Blair', 40.0, 'Compact island with simple internal roads; main access via government and private ferries from Port Blair and Havelock.[web:220][web:223]', '{"Beach","Relaxation","Photography","Snorkelling","Short_break"}', '{"Bharatpur Beach","Laxmanpur Beach","Sitapur Beach","Natural Rock Formation"}', '{"Glass-bottom boat rides and snorkelling at Bharatpur.[web:220][web:223]","Sunset viewing at Laxmanpur Beach.[web:220][web:223]","Sunrise at Sitapur Beach and cycling around island.[web:220][web:223]","Casual beach walks and photography"}', 'Small, laid-back island with multiple beaches offering sunrise, sunset and lagoon experiences in one compact circuit.[web:220][web:223]', 'Quiet interior village roads ideal for cycling.[web:223] | Less-crowded stretches of Laxmanpur away from main sunset point', 'Winter | Calm sea months November–April', 'Monsoon spells with rough seas and reduced ferries.[web:220]', 'December–March', 'June–September', '{"winter": "23-30\u00b0C", "summer": "26-33\u00b0C", "monsoon": "24-30\u00b0C"}'::jsonb, 'Tropical rainfall pattern similar to Havelock; heavy monsoon showers.', '{"Couples","Families","Slow_travellers","Budget_beach_lovers"}', '{"Slow_travellers": "Unhurried vibe with easy cycling and short distances between spots.[web:220]", "Couples": "Sunrise and sunset beaches with fewer crowds than Havelock."}'::jsonb, 'Limited nightlife; last ferry timings restrict arrival and departure windows; carry cash.', 1.0, 2.0, 3, 'Day 1: Arrive, Bharatpur Beach and Natural Rock Formation; Day 2: Sunrise at Sitapur and sunset at Laxmanpur; optional extra day for snorkelling and relaxation.[web:220][web:223]', 'Beachside resorts | Guesthouses | Eco-cottages', 'Simple restaurants near beaches serving Indian and some Bengali and seafood dishes.[web:220][web:223]', 9.0, 'Calm, small community; usual caution with water activities and sun exposure.', 'Limited 4G; some stays offer Wi‑Fi with variable speeds.', 'BSNL, Jio and Airtel in pockets', 'Very limited; best to carry cash from Port Blair.', 'Hindi | Bengali | Tamil | English (tourism)', FALSE, 'Not required', 'Fishing and farming-based island communities increasingly oriented to tourism.', 'Standard Indian festivals; no very large separate island event.', 'Modest attire away from beaches; respect fishing zones and local property.', 'Basic souvenirs | Shell items | Local snack stalls', 'Fresh fish curries | Bengali-style dishes at Neil Kendra.[web:223] | Coconut-based sweets and snacks', '{"accommodation_range": [1000, 2000], "food_range": [300, 600], "activities_range": [300, 700], "local_transport_range": [200, 500], "total_daily_range": [1800, 3800]}'::jsonb, '{"accommodation_range": [2000, 4500], "food_range": [500, 1000], "activities_range": [600, 1000], "local_transport_range": [300, 700], "total_daily_range": [3400, 7200]}'::jsonb, '{"accommodation_range": [4500, 12000], "food_range": [800, 1800], "activities_range": [800, 2000], "local_transport_range": [400, 900], "total_daily_range": [6500, 16700]}'::jsonb, 'Experience Neil Island (Shaheed Dweep) in Andaman and Nicobar Islands.', 'Rated as quieter and more relaxed than Havelock with beautiful, swimmable beaches and easy half- or full-day tours.', 'Improved jetties and more stay choices while still maintaining a relatively low-key vibe.', 'Island ecology is fragile; use reef-safe sunscreen, avoid littering and support small local-run stays.') ON CONFLICT (id) DO NOTHING;
INSERT INTO destinations (id, destination_name, state_id, city_id, district, region, latitude, longitude, altitude_m, popularity_score, accessibility, nearest_airport, nearest_railway, nearest_major_city, nearest_major_city_distance_km, road_connectivity, trip_types, primary_attractions, activities_available, unique_experiences, hidden_gems, best_seasons, avoid_seasons, peak_season, off_season, average_temperature, rainfall_pattern, ideal_for, ideal_for_why, special_considerations, minimum_days, ideal_days, maximum_days, suggested_itinerary, accommodation_types, food_scene, safety_rating, safety_notes, internet_connectivity, mobile_network, atm_availability, language_spoken, permits_required, permits_details, local_culture, festivals_events, local_customs, shopping_highlights, local_cuisine_must_try, budget_range_json, mid_range_json, luxury_range_json, description, user_reviews_summary, recent_developments, sustainability_notes) VALUES ('dest-33', 'Shillong', 'IN-ML', 'east-khasi-hills', 'East Khasi Hills', 'North East India', 25.5788, 91.8933, 1495, 7.0, 'Moderate', '{"name": "Shillong Airport (Umroi) / Guwahati", "distance_km": 30}'::jsonb, '{"name": "Guwahati (major railhead)", "distance_km": 100}'::jsonb, 'Guwahati', 100.0, 'Good hilly highway from Guwahati to Shillong with frequent shared cabs and buses.', '{"Hill_station","City_break","Music_culture","Gateway_destination"}', '{"Ward’s Lake","Police Bazaar (market)","Shillong Peak and viewpoints","Nearby waterfalls and lakes (like Umiam Lake en route)"}', '{"City walks and cafes","Market shopping","Short drives to viewpoints and nearby falls"}', 'Compact hill city often called the ''Scotland of the East'' with strong music scene and as a base for wider Meghalaya trips.[web:221][web:224]', 'Local cafes and live-music venues | Quiet neighbourhood walks away from main market', 'Winter | Post-monsoon', 'Heaviest monsoon spells with intense rainfall and fog', 'October–April, especially around Christmas and New Year', 'June–August heavy rain months', '{"winter": "6-20\u00b0C", "summer": "15-25\u00b0C", "monsoon": "14-22\u00b0C"}'::jsonb, 'High rainfall during monsoon, with occasional showers in other seasons.', '{"Families","Young_travellers","Music_and_cafe_lovers","Travellers_heading_to_Cherrapunji/Dawki"}', '{"Travellers_heading_to_Cherrapunji/Dawki": "Practical and pleasant base at start or end of Meghalaya itinerary.[web:221]", "Music_and_cafe_lovers": "Known for indie bands, cafes and youth culture."}'::jsonb, 'Traffic congestion in peak hours; book stays near areas of interest to reduce commute.', 1.0, 2.0, 3, 'Use Day 1–2 for Shillong sights and cafes, then continue 3–5 days towards Cherrapunji, Dawki and Krang Suri as part of larger Meghalaya plan.[web:221][web:224]', 'Hotels | Guesthouses | Homestays | Boutique stays', 'Wide variety of North Indian, Chinese, fast food and some Khasi cuisine; many cafes.', 8.0, 'Generally safe; normal city precautions; night travel to outskirts via reputed taxis.', 'Good 4G and broadband in city.', 'Jio | Airtel | Vi', 'Plentiful ATMs across city.', 'Khasi | English (widely) | Hindi (understood by many)', FALSE, 'Not required', 'Predominantly Khasi with matrilineal traditions and strong church presence.', 'Christmas celebrations, local cultural festivals and music events.', 'Respect church spaces and local norms; dress modestly when visiting religious or traditional areas.', 'Warm clothes and fashion in Police Bazaar | Local crafts and souvenirs', 'Jadoh (rice and meat dish) | Local pork preparations | Street snacks at markets', '{"accommodation_range": [800, 1500], "food_range": [250, 500], "activities_range": [200, 400], "local_transport_range": [200, 400], "total_daily_range": [1450, 2800]}'::jsonb, '{"accommodation_range": [1500, 3500], "food_range": [400, 800], "activities_range": [400, 800], "local_transport_range": [300, 600], "total_daily_range": [2600, 5700]}'::jsonb, '{"accommodation_range": [4000, 12000], "food_range": [800, 2000], "activities_range": [600, 1500], "local_transport_range": [400, 800], "total_daily_range": [5800, 16300]}'::jsonb, 'Experience Shillong in Meghalaya.', 'Appreciated as a pleasant hill base with urban comforts before/after exploring Meghalaya’s nature spots.', 'More cafes, boutique stays and organised Meghalaya tour packages.', 'Urban waste and traffic pollution are concerns; prefer walking and shared cabs where possible.') ON CONFLICT (id) DO NOTHING;
INSERT INTO destinations (id, destination_name, state_id, city_id, district, region, latitude, longitude, altitude_m, popularity_score, accessibility, nearest_airport, nearest_railway, nearest_major_city, nearest_major_city_distance_km, road_connectivity, trip_types, primary_attractions, activities_available, unique_experiences, hidden_gems, best_seasons, avoid_seasons, peak_season, off_season, average_temperature, rainfall_pattern, ideal_for, ideal_for_why, special_considerations, minimum_days, ideal_days, maximum_days, suggested_itinerary, accommodation_types, food_scene, safety_rating, safety_notes, internet_connectivity, mobile_network, atm_availability, language_spoken, permits_required, permits_details, local_culture, festivals_events, local_customs, shopping_highlights, local_cuisine_must_try, budget_range_json, mid_range_json, luxury_range_json, description, user_reviews_summary, recent_developments, sustainability_notes) VALUES ('dest-34', 'Cherrapunji & Mawsmai Area (Sohra region)', 'IN-ML', 'east-khasi-hills', 'East Khasi Hills', 'North East India', 25.27, 91.73, 1430, 8.0, 'Moderate', '{"name": "Shillong Airport / Guwahati", "distance_km": 60}'::jsonb, '{"name": "Guwahati", "distance_km": 150}'::jsonb, 'Shillong', 55.0, 'Hill roads from Shillong with frequent taxis and tours; winding but well travelled.[web:221][web:224]', '{"Waterfalls","Caves","Rain_destination","Short_treks"}', '{"Nohkalikai Falls","Seven Sisters Falls (seasonal flow)","Mawsmai Cave","Viewpoints over Bangladesh plains"}', '{"Waterfall viewpoint visits","Cave walks (easy sections at Mawsmai)","Short hikes to viewpoints","Monsoon rain experience (with care)"}', 'Extremely high rainfall region with dramatic cliffs, waterfalls and caves overlooking lowlands of Bangladesh.[web:221][web:224]', 'Less crowded viewpoints off main road | Small local homestays with valley views', 'Post-monsoon and winter for clear views; monsoon for intense waterfall volume if prepared for rain.[web:224]', 'Days of extreme rainfall and landslide warnings. | Very foggy days if priority is views.', 'October–April and some monsoon weekends', 'Heaviest continuous rain spells', '{"winter": "8-20\u00b0C", "summer": "15-25\u00b0C", "monsoon": "14-22\u00b0C"}'::jsonb, 'Among highest rainfall areas in the world; heavy and frequent showers in monsoon.[web:224]', '{"Waterfall_chasers","Nature_lovers","Monsoon_experience_seekers","Photographers"}', '{"Waterfall_chasers": "Multiple large falls visible from accessible viewpoints.", "Monsoon_experience_seekers": "Legendary rainfall and lush greenery."}'::jsonb, 'Carry good rain gear, non-slip footwear and be cautious near cliff edges; some viewpoints and caves may close in hazardous weather.', 1.0, 2.0, 3, 'Combine with nearby root-bridge region or Dawki in a 3–5 day Meghalaya circuit; allocate 1–2 days to falls and caves around Cherrapunji.[web:221][web:224]', 'Homestays | Guesthouses | Small resorts', 'Basic to mid-range eateries offering Indian and some local Khasi dishes.', 8.0, 'Weather-related risks more important than crime; heed local advice on landslides and slippery trails.', 'Patchy but present in town and some stays.', 'Jio | Airtel, variable coverage', 'Limited; best to withdraw in Shillong.', 'Khasi | English (widely) | Hindi (some)', FALSE, 'Not required', 'Khasi communities with matrilineal traditions and close relationship to land.', 'Local festivals and church events; nature is the main attraction.', 'Respect church and village spaces; avoid loud behaviour near religious and community areas.', 'Basic souvenirs | Local spices and oranges (in season)', 'Jadoh and Khasi pork dishes | Local teas and snacks', '{"accommodation_range": [800, 1500], "food_range": [250, 500], "activities_range": [200, 500], "local_transport_range": [300, 700], "total_daily_range": [1550, 3200]}'::jsonb, '{"accommodation_range": [1500, 3500], "food_range": [400, 800], "activities_range": [400, 800], "local_transport_range": [500, 900], "total_daily_range": [2800, 6000]}'::jsonb, '{"accommodation_range": [3500, 10000], "food_range": [700, 1800], "activities_range": [600, 1500], "local_transport_range": [700, 1200], "total_daily_range": [5500, 14500]}'::jsonb, 'Experience Cherrapunji & Mawsmai Area (Sohra region) in Meghalaya.', 'Loved for its dramatic landscapes and waterfalls; some find constant rain challenging but rewarding.', 'Improved viewpoints, safety railings and homestay network.', 'High rainfall system is sensitive to pollution; carry back waste and use eco-friendly products.') ON CONFLICT (id) DO NOTHING;
INSERT INTO destinations (id, destination_name, state_id, city_id, district, region, latitude, longitude, altitude_m, popularity_score, accessibility, nearest_airport, nearest_railway, nearest_major_city, nearest_major_city_distance_km, road_connectivity, trip_types, primary_attractions, activities_available, unique_experiences, hidden_gems, best_seasons, avoid_seasons, peak_season, off_season, average_temperature, rainfall_pattern, ideal_for, ideal_for_why, special_considerations, minimum_days, ideal_days, maximum_days, suggested_itinerary, accommodation_types, food_scene, safety_rating, safety_notes, internet_connectivity, mobile_network, atm_availability, language_spoken, permits_required, permits_details, local_culture, festivals_events, local_customs, shopping_highlights, local_cuisine_must_try, budget_range_json, mid_range_json, luxury_range_json, description, user_reviews_summary, recent_developments, sustainability_notes) VALUES ('dest-35', 'Dawki & Shnongpdeng', 'IN-ML', 'west-jaintia-hills', 'West Jaintia Hills', 'North East India', 25.2, 92.02, 150, 7.0, 'Moderate', '{"name": "Shillong Airport / Guwahati", "distance_km": 90}'::jsonb, '{"name": "Guwahati", "distance_km": 170}'::jsonb, 'Shillong', 80.0, 'Hill roads from Shillong via Pynursla/other routes; last stretch includes narrow winding roads to river bank.[web:221]', '{"River","Adventure","Camping","Photography"}', '{"Umngot River at Dawki and Shnongpdeng (crystal-clear water)[web:221]","Boating and kayaking stretches","Border town views towards Bangladesh"}', '{"Crystal-clear river boating","Kayaking, snorkelling and cliff jumping with operators","Camping by riverside (seasonal)","Short walks and suspension bridge views"}', 'Boat rides on clear river where boats appear to float on air in good conditions, with camping options along riverbank.[web:221]', 'Early-morning boat rides before crowds | Less busy camps slightly away from main Dawki bridge zone', 'Post-monsoon to winter when water is clearest (roughly November–February).[web:221]', 'Peak monsoon when river can be muddy and water levels/flow risky. | Very crowded holiday weekends if seeking quiet.', 'December–January and major holidays', 'Monsoon months and weekdays in shoulder seasons', '{"winter": "12-26\u00b0C", "summer": "22-32\u00b0C", "monsoon": "22-28\u00b0C"}'::jsonb, 'High rainfall region; river clarity drops in heavy rain periods.[web:221]', '{"Adventure_seekers","Friends_groups","Campers","Photographers"}', '{"Adventure_seekers": "Cliff jumps, kayaking and camping packages.", "Photographers": "Clear-water boat visuals and riverside landscapes."}'::jsonb, 'Water-sport safety gear and certified operators are essential; river conditions can change quickly; border area regulations apply.', 1.0, 1.0, 2, 'Often done as day trip from Shillong or combined with Mawlynnong; arrive by late morning for clearer light, enjoy boating and return or camp overnight.[web:221]', 'Riverside camps | Basic homestays | Guesthouses in nearby villages', 'Simple local stalls and food at camps; more variety in Shillong.', 7.0, 'Adventure-activity risks; insist on life jackets and avoid river in stormy conditions.', 'Limited mobile data along river.', 'Jio, Airtel (spotty)', 'Very limited; carry cash from Shillong.', 'Khasi | English (some) | Hindi (some)', FALSE, 'Not required', 'Border-area Khasi villages with river-based livelihoods.', 'Occasional local events; main draw is nature and activities.', 'Respect village property and river cleanliness; avoid loud music late at night in camp areas.', 'Small souvenirs | Local snacks', 'Simple rice and meat/fish thali from local eateries | Local tea and snacks', '{"accommodation_range": [800, 1500], "food_range": [250, 500], "activities_range": [400, 1000], "local_transport_range": [400, 800], "total_daily_range": [1850, 3800]}'::jsonb, '{"accommodation_range": [1500, 3000], "food_range": [400, 800], "activities_range": [800, 1500], "local_transport_range": [500, 900], "total_daily_range": [3200, 6200]}'::jsonb, '{"accommodation_range": [3000, 8000], "food_range": [700, 1500], "activities_range": [1200, 2500], "local_transport_range": [700, 1200], "total_daily_range": [5600, 13200]}'::jsonb, 'Experience Dawki & Shnongpdeng in Meghalaya.', 'Famous for ‘glass-clear’ river views; some note crowding on busy days but still consider it a must-see.', 'More organised water-sport operators and designated camping zones.', 'Increasing tourist pressure on river; avoid plastics and follow operator rules to keep water clean.') ON CONFLICT (id) DO NOTHING;
INSERT INTO destinations (id, destination_name, state_id, city_id, district, region, latitude, longitude, altitude_m, popularity_score, accessibility, nearest_airport, nearest_railway, nearest_major_city, nearest_major_city_distance_km, road_connectivity, trip_types, primary_attractions, activities_available, unique_experiences, hidden_gems, best_seasons, avoid_seasons, peak_season, off_season, average_temperature, rainfall_pattern, ideal_for, ideal_for_why, special_considerations, minimum_days, ideal_days, maximum_days, suggested_itinerary, accommodation_types, food_scene, safety_rating, safety_notes, internet_connectivity, mobile_network, atm_availability, language_spoken, permits_required, permits_details, local_culture, festivals_events, local_customs, shopping_highlights, local_cuisine_must_try, budget_range_json, mid_range_json, luxury_range_json, description, user_reviews_summary, recent_developments, sustainability_notes) VALUES ('dest-36', 'Krang Suri Falls', 'IN-ML', 'west-jaintia-hills', 'West Jaintia Hills', 'North East India', 25.34, 92.25, 800, 6.0, 'Moderate', '{"name": "Shillong Airport / Guwahati", "distance_km": 90}'::jsonb, '{"name": "Guwahati", "distance_km": 180}'::jsonb, 'Jowai', 30.0, 'Road from Jowai with last stretch on narrower hilly roads; walks and steps from parking to falls.[web:224]', '{"Waterfall","Swimming","Day_trip","Photography"}', '{"Turquoise-blue plunge pool","Curtain-like waterfall with viewing platforms"}', '{"Guided swimming in designated safe area (with life jackets where allowed).[web:224]","Photography from walkways and viewpoints.[web:224]","Picnics and relaxation near falls"}', 'Striking turquoise waterfall pool that looks almost unreal in sunlight, reached via a scenic trail and steps.[web:224]', 'Early-morning visits with fewer crowds and best light.[web:224]', 'Post-monsoon and winter for clearer water and safe access.[web:224]', 'Periods of very heavy rain or unsafe flow when access may be restricted.[web:224]', 'November–February and holiday weekends', 'Monsoon and very rainy spells', '{"winter": "10-24\u00b0C", "summer": "18-28\u00b0C", "monsoon": "18-24\u00b0C"}'::jsonb, 'Heavy monsoon rainfall; water colour and flow vary by season.[web:224]', '{"Waterfall_chasers","Photographers","Friends_groups"}', '{"Waterfall_chasers": "Considered one of Meghalaya\u2019s prettiest falls with easily accessible viewpoints.[web:224]", "Photographers": "Turquoise pool and misty spray create dramatic visuals."}'::jsonb, 'Steps and paths can be slippery; follow all safety boards and use lifejackets where required; check local conditions before planning swim-focused trips.', 1.0, 1.0, 1, 'Typically combined with Dawki or Jowai area sights in a day trip; spend 2–3 hours at falls for walking, photos and optional dip.[web:221][web:224]', 'Stay in Jowai or Shillong and visit as day trip | Very limited basic stays near falls area', 'Small stalls and basic eateries near parking; carry snacks and water.', 7.0, 'Respect barriers; do not venture beyond marked swim zones; rock surfaces can be slippery.', 'Limited mobile signal around falls.', 'Jio, Airtel (spotty)', 'ATMs in Jowai; not at falls.', 'Pnar/Khasi | English (some) | Hindi (some)', FALSE, 'Not required', 'Falls are in Jaintia region with local communities managing some facilities.', 'No major standalone festival; visited as scenic nature spot.', 'Follow local rules, especially regarding swimwear and behaviour around families.', 'Local snacks from stalls | Basic souvenirs from nearby markets', 'Simple rice plates and snacks from local eateries', '{"accommodation_range": [600, 1200], "food_range": [200, 400], "activities_range": [200, 500], "local_transport_range": [300, 600], "total_daily_range": [1300, 2700]}'::jsonb, '{"accommodation_range": [1200, 2500], "food_range": [400, 800], "activities_range": [400, 800], "local_transport_range": [400, 800], "total_daily_range": [2400, 4900]}'::jsonb, '{"accommodation_range": [2500, 6000], "food_range": [600, 1500], "activities_range": [600, 1500], "local_transport_range": [500, 900], "total_daily_range": [4200, 9900]}'::jsonb, 'Experience Krang Suri Falls in Meghalaya.', 'Frequently mentioned as a favourite waterfall in Meghalaya for its colour and atmosphere.', 'Wooden walkways, viewpoints and safety measures improved in recent years.', 'Keep the pool and surroundings clean; avoid soaps and shampoos in water and carry trash back out.') ON CONFLICT (id) DO NOTHING;
